def run_length(s: str) -> str:
    """See SPEC.md."""
    result = []
    for char, group in _group_runs(s):
        result.append(char)
        result.append(str(len(group)))
    return "".join(result)


def _group_runs(s: str):
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        yield s[i], s[i:j]
        i = j

from itertools import groupby


def run_length(s: str) -> str:
    """See SPEC.md."""
    return "".join(ch + str(len(list(g))) for ch, g in groupby(s))

